item.description:
&lt;h2 id=&#34;cve-2025-15029-sql-injection&#34;&gt;CVE-2025-15029: SQL Injection
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;CVE Publication: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2025-15029&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2025-15029&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;summary&#34;&gt;Summary
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;An unauthenticated user is able to introduce SQL Injection using the AWIE export module.&lt;/p&gt;
&lt;h2 id=&#34;impact&#34;&gt;Impact
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
  &lt;ul&gt;
    &lt;li&gt;Unauthorized access to sensitive data (e.g., users, passwords, logs).&lt;/li&gt;
    &lt;li&gt;Database enumeration (schemas, tables, users, versions).&lt;/li&gt;
    &lt;li&gt;Escalation to RCE depending on DB configuration (e.g., xp_cmdshell, UDFs).&lt;/li&gt;
    &lt;li&gt;Full compromise of the application if chained with other vulnerabilities.&lt;/li&gt;
    &lt;li&gt;This issue affects all users and environments, as it does not require authentication and is reachable via a public endpoint.&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;

item.content:encoded:
&lt;h2 id=&#34;cve-2025-15029-sql-injection&#34;&gt;CVE-2025-15029: SQL Injection
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;CVE Publication: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2025-15029&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2025-15029&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;summary&#34;&gt;Summary
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;An unauthenticated user is able to introduce SQL Injection using the AWIE export module.&lt;/p&gt;
&lt;h2 id=&#34;impact&#34;&gt;Impact
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
  &lt;ul&gt;
    &lt;li&gt;Unauthorized access to sensitive data (e.g., users, passwords, logs).&lt;/li&gt;
    &lt;li&gt;Database enumeration (schemas, tables, users, versions).&lt;/li&gt;
    &lt;li&gt;Escalation to RCE depending on DB configuration (e.g., xp_cmdshell, UDFs).&lt;/li&gt;
    &lt;li&gt;Full compromise of the application if chained with other vulnerabilities.&lt;/li&gt;
    &lt;li&gt;This issue affects all users and environments, as it does not require authentication and is reachable via a public endpoint.&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;
&lt;h2 id=&#34;reference&#34;&gt;Reference
&lt;/h2&gt;&lt;p&gt;&lt;em&gt;&lt;strong&gt;&lt;a class=&#34;link&#34; href=&#34;https://thewatch.centreon.com/latest-security-bulletins-64/cve-2025-15029-centreon-awie-critical-severity-5356&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
