&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Referer: http://localhost/intranet/educar_consulta_movimento_mensal_lst.php?ano=2025&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;ref_cod_instituicao=1&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;ref_cod_escola=4&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;ref_cod_curso=3&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;ref_cod_serie=&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;ref_cod_turma=&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;data_inicial=01%2F08%2F2025&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;data_final=31%2F08%2F2025&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;modalidade=1
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Cookie: i_educar_session=[low_privileged cookie]
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Upgrade-Insecure-Requests: 1
