	width=&#34;1572&#34;
	height=&#34;707&#34;
	srcset=&#34;/p/cve-2025-10012/image_hu_988aafc9dd1fbe7.png 480w, /p/cve-2025-10012/image_hu_7d467cabf908a825.png 1024w&#34;
	loading=&#34;lazy&#34;


