	height=&#34;533&#34;
	srcset=&#34;/p/cve-2025-10013/image_hu_5ca2ea85ab6696dd.png 480w, /p/cve-2025-10013/image_hu_deb570b2049417e1.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
