	height=&#34;436&#34;
	srcset=&#34;/p/cve-2025-10013/image-1_hu_8cd5643a33eabd47.png 480w, /p/cve-2025-10013/image-1_hu_f205df0666d7bd3a.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
		data-flex-grow=&#34;214&#34;
		data-flex-basis=&#34;515px&#34;

