	width=&#34;1177&#34;
	height=&#34;1049&#34;
	srcset=&#34;/p/cve-2025-9684/image_hu_4da7a86622a45df0.png 480w, /p/cve-2025-9684/image_hu_1f080892d45bc258.png 1024w&#34;
