	srcset=&#34;/p/cve-2025-9107/image_hu_8aadeff40c8f3d51.png 480w, /p/cve-2025-9107/image_hu_3012aeb2aec1845.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
