&lt;/h2&gt;&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;https://github.com/CVE-Hunters/CVE/blob/main/i-educar/CVE-2025-8544.md&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://github.com/CVE-Hunters/CVE/blob/main/i-educar/CVE-2025-8544.md&lt;/a&gt;&lt;/p&gt;
