	loading=&#34;lazy&#34;


 /&gt;&lt;/a&gt; &lt;a class=&#34;link&#34; href=&#34;https://www.linkedin.com/in/rafael-corvino/&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;Rafael Corvino&lt;/a&gt;&lt;/p&gt;
