	width=&#34;1780&#34;
	height=&#34;429&#34;
	srcset=&#34;/p/cve-2024-57034/image_hu_34c11f32ed2b11e5.png 480w, /p/cve-2024-57034/image_hu_c46263e9b2f8aae6.png 1024w&#34;
	loading=&#34;lazy&#34;


		class=&#34;gallery-image&#34; 
		data-flex-grow=&#34;414&#34;
		data-flex-basis=&#34;995px&#34;

 /&gt;&lt;/p&gt;
&lt;h2 id=&#34;references&#34;&gt;References
&lt;/h2&gt;&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;https://github.com/LabRedesCefetRJ/WeGIA/issues/825&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://github.com/nilsonLazarin/WeGIA/issues/825&lt;/a&gt;&lt;/p&gt;
