		data-flex-basis=&#34;564px&#34;

 /&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/p/cve-2025-22614/402262348-475ba360-6014-4b73-8581-c1909da8ccc4.png&#34;
	width=&#34;806&#34;
	height=&#34;208&#34;
	srcset=&#34;/p/cve-2025-22614/402262348-475ba360-6014-4b73-8581-c1909da8ccc4_hu_e383c719baa38c71.png 480w, /p/cve-2025-22614/402262348-475ba360-6014-4b73-8581-c1909da8ccc4_hu_fa90d728b9bcefea.png 1024w&#34;
