	width=&#34;805&#34;
	height=&#34;222&#34;
	srcset=&#34;/p/cve-2025-22618/402269279-a461d356-14f1-4517-be79-e9cd112fd6c1_hu_8639761381340b0.png 480w, /p/cve-2025-22618/402269279-a461d356-14f1-4517-be79-e9cd112fd6c1_hu_f8134686c8ad53cb.png 1024w&#34;
