		data-flex-basis=&#34;695px&#34;

 /&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/p/cve-2025-23030/402271164-d511ae4b-88e1-4198-943d-62a8f81fe823.png&#34;
	width=&#34;806&#34;
	height=&#34;233&#34;
	srcset=&#34;/p/cve-2025-23030/402271164-d511ae4b-88e1-4198-943d-62a8f81fe823_hu_b90e40199c08726a.png 480w, /p/cve-2025-23030/402271164-d511ae4b-88e1-4198-943d-62a8f81fe823_hu_d1cbcefed7c53e69.png 1024w&#34;
