	srcset=&#34;/p/cve-2025-23031/402278153-dc6daac0-ec0e-44e7-89cf-44071056103e_hu_b47fb1291cd2325a.png 480w, /p/cve-2025-23031/402278153-dc6daac0-ec0e-44e7-89cf-44071056103e_hu_2c4c51887bda5c54.png 1024w&#34;
