		data-flex-basis=&#34;600px&#34;

 /&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/p/cve-2025-23031/402278156-33fae2c0-653a-43bd-b4f8-7352e6297075.png&#34;
	width=&#34;805&#34;
	height=&#34;259&#34;
	srcset=&#34;/p/cve-2025-23031/402278156-33fae2c0-653a-43bd-b4f8-7352e6297075_hu_11d348064d7422c4.png 480w, /p/cve-2025-23031/402278156-33fae2c0-653a-43bd-b4f8-7352e6297075_hu_afa5df58c4923029.png 1024w&#34;
